// Package uuidv7 generates time-ordered UUIDv7 identifiers (RFC 9562) in the application,
// because Postgres 15 has no native generator.
package uuidv7

import "github.com/google/uuid"

// New returns a new UUIDv7. IDs generated by one process are strictly increasing: the
// generator keeps sub-millisecond state, so IDs created within the same millisecond still sort.
func New() uuid.UUID {
	id, err := uuid.NewV7()
	if err != nil {
		// Only fails if crypto/rand fails, which the Go runtime treats as fatal anyway.
		panic("uuidv7: " + err.Error())
	}
	return id
}
